using System;using System.IO;using System.Linq;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.PlottingServices;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoPlot {const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
[CommandMethod("CODEXUGOPLOTPREVIEW")]public void Run(){try{var doc=AcApp.DocumentManager.MdiActiveDocument;var db=doc.Database;LayoutManager.Current.CurrentLayout="УГО";using(var tr=db.TransactionManager.StartTransaction()){var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);var zero=(LayerTableRecord)tr.GetObject(lt["0"],OpenMode.ForWrite);zero.IsPlottable=true;var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var layout=(Layout)tr.GetObject(ld.GetAt("УГО"),OpenMode.ForRead);var paper=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForRead);foreach(ObjectId id in paper){if(tr.GetObject(id,OpenMode.ForRead) is Viewport v){v.UpgradeOpen();v.Layer="Defpoints";}}
 using(var ps=new PlotSettings(layout.ModelType)){ps.CopyFrom(layout);var pv=PlotSettingsValidator.Current;pv.SetPlotConfigurationName(ps,"DWG To PDF.pc3",null);pv.RefreshLists(ps);var media=pv.GetCanonicalMediaNameList(ps).Cast<string>().First(x=>x.Contains("A4")&&x.Contains("210.00")&&x.Contains("297.00")&&x.Contains("full_bleed"));pv.SetCanonicalMediaName(ps,media);pv.SetPlotPaperUnits(ps,PlotPaperUnit.Millimeters);pv.SetPlotRotation(ps,PlotRotation.Degrees000);pv.SetPlotType(ps,Autodesk.AutoCAD.DatabaseServices.PlotType.Window);pv.SetPlotWindowArea(ps,new Extents2d(0,0,210,297));pv.SetUseStandardScale(ps,true);pv.SetStdScaleType(ps,StdScaleType.StdScale1To1);pv.SetPlotCentered(ps,true);ps.PlotPlotStyles=false;
 var info=new PlotInfo{Layout=layout.ObjectId,OverrideSettings=ps};var validator=new PlotInfoValidator{MediaMatchingPolicy=MatchingPolicy.MatchEnabled};validator.Validate(info);using(var pe=PlotFactory.CreatePublishEngine()){pe.BeginPlot(null,null);pe.BeginDocument(info,doc.Name,null,1,true,Path.Combine(Folder,"Ugo_preview.pdf"));var page=new PlotPageInfo();pe.BeginPage(page,info,true,null);pe.BeginGenerateGraphics(null);pe.EndGenerateGraphics(null);pe.EndPage(null);pe.EndDocument(null);pe.EndPlot(null);}}
 tr.Commit();}File.WriteAllText(Path.Combine(Folder,"plot_ok.txt"),"PDF created");}catch(System.Exception e){File.WriteAllText(Path.Combine(Folder,"plot_error.txt"),e.ToString());}}
}